 "send1_time_r": "Time R",
 "send1_ms_l": "Time L",
 "send1_ms_r": "Time R",
 "send1_feedback": "Feedback",
 "send1_tone": "Tone",
 "send1_pingpong": "Ping-Pong",
 "send1_return": "Return",
 "send2_type": "Type",
 "send2_size": "Size",
 "send2_damp": "Damping",
 "send2_predelay": "Pre-delay",
 "send2_diffusion": "Diffusion",
 "send2_decay": "Decay",
 "send2_hold": "Gate Hold",
 "send2_tail": "Tail Decay",
 "send2_length": "Length",
 "send2_shape": "Shape",
